import sys
from collections import Counter

def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return

    try:
        k = int(lines[0].strip())
    except ValueError:
        return

    counts = Counter()

    for line in lines[1:]:
        parts = line.split(None, 1)
        if not parts:
            continue
        token = parts[0]
        if len(token) > 1 and token[0] == 'E' and token[1:].isdigit():
            counts[token] += 1

    top = sorted(counts.items(), key=lambda item: (-item[1], item[0]))[:max(k, 0)]

    if top:
        sys.stdout.write('\n'.join(f'{code} {amount}' for code, amount in top))

if __name__ == '__main__':
    main()

