import sys
from collections import deque

def main():
    owner = {}
    queues = {}
    out = []

    for line in sys.stdin.buffer:
        parts = line.split()
        if not parts:
            continue

        op = parts[0]
        txn = parts[1]
        lock = parts[2]

        if op == b'ACQ':
            current = owner.get(lock)
            if current is None:
                owner[lock] = txn
                out.append(b'GRANTED ' + txn + b' ' + lock)
            elif current == txn:
                out.append(b'ALREADY ' + txn + b' ' + lock)
            else:
                q = queues.get(lock)
                if q is None:
                    q = deque()
                    queues[lock] = q
                q.append(txn)
                out.append(b'WAIT ' + txn + b' ' + lock)
        else:  # REL
            if owner.get(lock) != txn:
                out.append(b'IGNORED ' + txn + b' ' + lock)
            else:
                q = queues.get(lock)
                if q:
                    nxt = q.popleft()
                    owner[lock] = nxt
                    if not q:
                        del queues[lock]
                    out.append(b'RELEASED ' + txn + b' ' + lock + b' GRANTED ' + nxt)
                else:
                    del owner[lock]
                    out.append(b'RELEASED ' + txn + b' ' + lock)

    if out:
        sys.stdout.buffer.write(b'\n'.join(out) + b'\n')

if __name__ == '__main__':
    main()

